package com.astra.config.aspect;
import com.astra.audit.entity.AuditLog; import com.astra.audit.service.AuditLogService; import jakarta.servlet.http.HttpServletRequest; import org.aspectj.lang.*; import org.aspectj.lang.annotation.*; import org.springframework.stereotype.Component; import org.springframework.web.context.request.*;
@Aspect @Component public class AuditAspect { private final AuditLogService audit; public AuditAspect(AuditLogService audit){this.audit=audit;} @Around("execution(* com.astra..controller..*(..))") public Object around(ProceedingJoinPoint jp)throws Throwable{long start=System.currentTimeMillis(); String outcome="SUCCESS"; try{return jp.proceed();}catch(Throwable t){outcome="FAILED";throw t;}finally{try{HttpServletRequest r=((ServletRequestAttributes)RequestContextHolder.getRequestAttributes()).getRequest(); var auth=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication(); audit.record(AuditLog.builder().username(auth==null?null:auth.getName()).action(jp.getSignature().getName()).httpMethod(r.getMethod()).endpoint(r.getRequestURI()).outcome(outcome).durationMs(System.currentTimeMillis()-start).build());}catch(Exception ignored){}}} }
